//! A history of what changed, newest entry first.

use std::collections::BTreeSet;

use anyhow::{bail, Result};

use crate::diff::{diff, Change};
use crate::model::Container;
use crate::render::{code, MARKER};

/// Path of the changelog, relative to the output folder.
pub const PATH: &str = "changelog.md";

fn header() -> String {
    format!(
        "{MARKER}\n\
         <!-- Generated by cadastre. Entries are added at the top; do not edit. -->\n\n\
         # Changelog\n\n\
         Changes to the running containers, newest first. Times are UTC.\n\n"
    )
}

/// The entry describing the move from `previous` to `current`.
///
/// `previous` is `None` on the first run, which yields an initial entry.
/// Returns `None` when nothing worth recording changed.
pub fn entry(
    timestamp: &str,
    previous: Option<&[Container]>,
    current: &[Container],
) -> Option<String> {
    let lines = match previous {
        None => vec![initial_line(current)],
        Some(previous) => {
            let changes = diff(previous, current);
            if changes.is_empty() {
                return None;
            }
            changes.iter().map(describe).collect()
        }
    };
    Some(format!("## {timestamp}\n\n{}\n\n", lines.join("\n")))
}

fn initial_line(containers: &[Container]) -> String {
    let stacks: BTreeSet<&str> = containers.iter().map(|c| c.stack()).collect();
    format!(
        "Initial snapshot: {} container{} in {} stack{}.",
        containers.len(),
        plural(containers.len()),
        stacks.len(),
        plural(stacks.len())
    )
}

fn plural(n: usize) -> &'static str {
    if n == 1 {
        ""
    } else {
        "s"
    }
}

fn describe(change: &Change) -> String {
    match change {
        Change::Added { name, image } => {
            format!("- Added {} ({})", code(name), code(image))
        }
        Change::Removed { name } => format!("- Removed {}", code(name)),
        Change::ImageChanged { name, from, to } => {
            format!(
                "- Image of {} changed: {} → {}",
                code(name),
                code(from),
                code(to)
            )
        }
        Change::Reconfigured { name, fields } => {
            format!("- Reconfigured {}: {}", code(name), fields.join(", "))
        }
    }
}

/// Puts `entry` at the top of the changelog.
///
/// A file that does not carry the generated marker was written by a person,
/// and is not overwritten: that is an error rather than a silent clobber.
pub fn prepend(existing: Option<&str>, entry: &str) -> Result<String> {
    let Some(text) = existing else {
        return Ok(format!("{}{entry}", header()));
    };
    if !text.contains(MARKER) {
        bail!("{PATH} exists but was not generated by cadastre; move it away or remove it");
    }
    match text.find("\n## ") {
        Some(index) => {
            let (head, tail) = text.split_at(index + 1);
            Ok(format!("{head}{entry}{tail}"))
        }
        None => {
            let mut result = text.trim_end().to_string();
            result.push_str("\n\n");
            result.push_str(entry);
            Ok(result)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;

    fn container(name: &str, project: Option<&str>) -> Container {
        Container {
            name: name.into(),
            image: "nginx:1".into(),
            image_id: "sha256:aaaaaaaaaaaaaaaa".into(),
            version: None,
            project: project.map(String::from),
            service: None,
            restart_policy: "no".into(),
            network_mode: "default".into(),
            ports: vec![],
            mounts: vec![],
            networks: vec![],
            env_keys: vec![],
            labels: BTreeMap::new(),
        }
    }

    #[test]
    fn the_first_run_records_an_initial_snapshot() {
        let now = [container("a", Some("x")), container("b", None)];
        let text = entry("2026-01-01T00:00:00Z", None, &now).unwrap();
        assert_eq!(
            text,
            "## 2026-01-01T00:00:00Z\n\nInitial snapshot: 2 containers in 2 stacks.\n\n"
        );
    }

    #[test]
    fn no_change_means_no_entry() {
        let state = [container("a", None)];
        assert_eq!(entry("t", Some(&state), &state), None);
    }

    #[test]
    fn changes_are_listed_one_per_line() {
        let old = [container("gone", None), container("kept", None)];
        let mut kept = container("kept", None);
        kept.image_id = "sha256:bbbbbbbbbbbbbbbb".into();
        let new = [kept, container("fresh", None)];
        let text = entry("t", Some(&old), &new).unwrap();
        assert!(text.contains("- Added `fresh` (`nginx:1`)"), "{text}");
        assert!(text.contains("- Removed `gone`"), "{text}");
        assert!(
            text.contains(
                "- Image of `kept` changed: `nginx:1 (aaaaaaaaaaaa)` → `nginx:1 (bbbbbbbbbbbb)`"
            ),
            "{text}"
        );
    }

    #[test]
    fn a_hostile_name_stays_inside_its_code_span() {
        let text = entry("t", Some(&[]), &[container("x`\n# injected", None)]).unwrap();
        assert!(!text.contains("\n# injected"), "{text}");
    }

    #[test]
    fn the_first_entry_creates_the_file_with_its_header() {
        let text = prepend(None, "## t1\n\nbody\n\n").unwrap();
        assert!(text.starts_with(MARKER));
        assert!(text.contains("# Changelog"));
        assert!(text.ends_with("## t1\n\nbody\n\n"));
    }

    #[test]
    fn new_entries_go_above_older_ones() {
        let first = prepend(None, "## t1\n\none\n\n").unwrap();
        let second = prepend(Some(&first), "## t2\n\ntwo\n\n").unwrap();
        let t1 = second.find("## t1").unwrap();
        let t2 = second.find("## t2").unwrap();
        assert!(t2 < t1, "{second}");
        assert_eq!(second.matches("# Changelog").count(), 1);
    }

    #[test]
    fn a_changelog_written_by_a_person_is_not_clobbered() {
        let error = prepend(Some("# My own changelog\n"), "## t\n\nx\n\n").unwrap_err();
        assert!(format!("{error:#}").contains("not generated"), "{error:#}");
    }
}
